import sys
from dataclasses import dataclass, field
from pathlib import Path

try:
    import yaml
except ImportError:  # pragma: no cover
    sys.exit("CSEF scanner needs PyYAML: pip install pyyaml")

TOOL_NAME = "csef-scan"
